package com.mlserve.inference

import scala.concurrent.{Future, ExecutionContext}
import scala.concurrent.ExecutionContext.Implicits.global
import java.net.{URI, URLDecoder}
import java.nio.charset.StandardCharsets

// Simplified HTTP abstractions for the ML inference server
case class HttpRequest(method: String, path: String, headers: Map[String, String], queryParams: Map[String, String], body: String)
case class HttpResponse(status: Int, headers: Map[String, String], body: String)

object RedirectPolicy {
  // Allowed redirect domains for model endpoint routing
  private val allowedDomains: Set[String] = Set(
    "models.internal.mlserve.io",
    "inference.mlserve.io",
    "api.mlserve.io",
    "cdn.mlserve.io"
  )

  // Parse and normalize the target URI
  def normalizeUri(raw: String): String = {
    val decoded = URLDecoder.decode(raw, StandardCharsets.UTF_8.name())
    decoded.replaceAll("\\s+", "")
  }

  // Extract the effective host from a URI string
  def extractHost(uriStr: String): Option[String] = {
    try {
      val uri = new URI(uriStr)
      Option(uri.getHost).map(_.toLowerCase)
    } catch {
      case _: Exception => None
    }
  }

  // Validate that the redirect target is within allowed domains
  def isAllowedRedirect(target: String): Boolean = {
    val normalized = normalizeUri(target)
    extractHost(normalized) match {
      case Some(host) =>
        allowedDomains.exists(domain => host == domain || host.endsWith("." + domain))
      case None =>
        // Relative paths are allowed
        !normalized.contains("://") && !normalized.startsWith("//")
    }
  }
}

object ModelRegistry {
  // Simulated model endpoint registry
  private val modelEndpoints: Map[String, String] = Map(
    "resnet50" -> "https://models.internal.mlserve.io/v2/resnet50/infer",
    "bert-base" -> "https://models.internal.mlserve.io/v2/bert-base/infer",
    "gpt2-small" -> "https://inference.mlserve.io/v2/gpt2-small/infer"
  )

  def getEndpoint(modelId: String): Option[String] = modelEndpoints.get(modelId)
}

class InferenceRouter {

  // Route inference request to appropriate model backend
  def routeInference(request: HttpRequest): Future[HttpResponse] = Future {
    val modelId = request.queryParams.getOrElse("model", "")
    val callbackUrl = request.queryParams.get("callback")

    ModelRegistry.getEndpoint(modelId) match {
      case Some(endpoint) =>
        // Process inference and redirect to callback if provided
        val redirectTarget = callbackUrl.getOrElse(endpoint)
        performRedirect(redirectTarget, request)
      case None =>
        HttpResponse(404, Map.empty, s"Model '$modelId' not found")
    }
  }

  // Handle post-inference redirect with validation
  private def performRedirect(target: String, originalRequest: HttpRequest): HttpResponse = {
    val validatedTarget = validateAndResolveTarget(target, originalRequest)
    HttpResponse(302, Map("Location" -> validatedTarget), "")
  }

  // Multi-step validation: normalize, resolve relative paths, check policy
  private def validateAndResolveTarget(target: String, request: HttpRequest): String = {
    // Validate the target directly without host-header-based resolution
    if (RedirectPolicy.isAllowedRedirect(target)) {
      RedirectPolicy.normalizeUri(target)
    } else {
      "https://api.mlserve.io/error?reason=blocked_redirect"
    }
  }
}

class AsyncInferenceService {
  private val router = new InferenceRouter()

  // Main entry point for inference requests with async model loading
  def handleRequest(request: HttpRequest): Future[HttpResponse] = {
    val preflightCheck = validateRequestHeaders(request)

    preflightCheck.flatMap {
      case true => router.routeInference(request)
      case false => Future.successful(HttpResponse(400, Map.empty, "Invalid request"))
    }
  }

  private def validateRequestHeaders(request: HttpRequest): Future[Boolean] = Future {
    request.headers.contains("Authorization") || 
    request.queryParams.contains("api_key")
  }
}

// Application entry point
object MLInferenceServer extends App {
  val service = new AsyncInferenceService()

  // Example: simulate incoming request
  val testRequest = HttpRequest(
